// The full element and isotope dataset for the gallery, generated by
// scripts/gen-elements.py from the mendeleev package (configurations, radii,
// physical properties, discovery and text) and the conventional list of
// observationally stable nuclides. Everything derived from it that the
// renderer needs (subshell structure, Slater screening, the inherited core)
// is computed here, once, so the rest of the gallery works with plain objects.

import RAW from '../data/elements.json';
import RAW_ISO from '../data/isotopes.json';

export type Block = 's' | 'p' | 'd' | 'f';
export const BLOCKS: Block[] = ['s', 'p', 'd', 'f'];
export const L_OF: Record<Block, number> = { s: 0, p: 1, d: 2, f: 3 };

export interface Subshell {
  key: string; // "3d"
  n: number;
  l: Block;
  count: number; // electrons in it
  capacity: number;
  /** True when this layer is part of the inherited noble-gas core. */
  core: boolean;
  /** Slater effective nuclear charge for this subshell. */
  zeff: number;
  /** Mean radius of the hydrogen-like orbital with that zeff, in Bohr radii. */
  meanRadius: number;
}

export interface Isotope {
  a: number;
  mass: number | null;
  abundance: number | null; // percent
  halfLife: number | null; // seconds; null for stable or unknown
  spin: string | null;
  stable: boolean;
}

export interface Element {
  z: number;
  symbol: string;
  name: string;
  weight: number | null;
  period: number;
  group: number | null;
  block: Block;
  series: string;
  subshells: Subshell[];
  configuration: string; // "1s2 2s2 2p6 ..."
  /** Noble-gas core symbol, e.g. "Ne", or null for H to Ne. */
  core: string | null;
  shells: number;
  orbitals: number; // occupied orbitals
  unpaired: number;
  /** Mass number of the most abundant stable isotope, or the longest-lived one. */
  commonA: number;
  /** Van der Waals radius in pm (Bondi/Mantina). */
  vdw: number;
  vdwEstimated: boolean;
  covalent: number | null;
  density: number | null; // g/cm3
  melt: number | null; // K
  boil: number | null; // K
  electronegativity: number | null;
  electronAffinity: number | null; // eV
  ionisation: number | null; // eV, first
  oxidation: number[];
  cpk: string | null;
  crust: number | null; // mg/kg
  sea: number | null; // mg/L
  geochemical: string | null;
  discoveryYear: number | null;
  discoverers: string | null;
  discoveryPlace: string | null;
  nameOrigin: string | null;
  description: string | null;
  uses: string | null;
  sources: string | null;
  stableIsotopes: number;
  isotopes: Isotope[];
  /** Nucleus radius, 1.2 fm x A^(1/3). */
  nucleusRadius: number;
}

interface RawElement {
  z: number; s: string; n: string; w: number | null; p: number; g: number | null; b: Block; ser: string;
  subs: string[]; A: number; vdw: number; vdwEst: boolean; cov: number | null; dens: number | null;
  mp: number | null; bp: number | null; en: number | null; ea: number | null; ie: number | null; ox: number[];
  cpk: string | null; crust: number | null; sea: number | null; geo: string | null; year: number | null;
  who: string | null; where: string | null; origin: string | null; desc: string | null; uses: string | null;
  src: string | null; stab: number; nIso: number;
}
type RawIsotope = [number, number | null, number | null, number | null, string | null, boolean];

const NOBLE: Record<number, string> = { 2: 'He', 10: 'Ne', 18: 'Ar', 36: 'Kr', 54: 'Xe', 86: 'Rn' };
/** Slater's n* for the principal quantum number. */
const N_STAR = [0, 1, 2, 3, 3.7, 4.0, 4.2, 4.4];
/** Slater groups in order: 1s, 2sp, 3sp, 3d, 4sp, 4d, 4f, 5sp, 5d, 5f, 6sp, 6d, 7sp, 7p... */
const groupKey = (n: number, l: Block) => (l === 's' || l === 'p' ? `${n}sp` : `${n}${l}`);
const GROUP_ORDER = ['1s', '2sp', '3sp', '3d', '4sp', '4d', '4f', '5sp', '5d', '5f', '6sp', '6d', '7sp', '6f', '7d', '8sp'];

function parseSub(s: string): { n: number; l: Block; count: number } {
  return { n: Number(s[0]), l: s[1] as Block, count: Number(s.slice(2)) };
}

/** Slater's rules: effective charge seen by an electron in each subshell. */
function slater(z: number, subs: { n: number; l: Block; count: number }[]): number[] {
  const groupCount: Record<string, number> = {};
  for (const s of subs) groupCount[groupKey(s.n, s.l)] = (groupCount[groupKey(s.n, s.l)] ?? 0) + s.count;
  return subs.map((s) => {
    const key = groupKey(s.n, s.l);
    const gi = GROUP_ORDER.indexOf(key);
    let shield = (groupCount[key] - 1) * (key === '1s' ? 0.3 : 0.35);
    GROUP_ORDER.forEach((g, j) => {
      if (j >= gi || !groupCount[g]) return;
      const gn = Number(g[0]);
      if (s.l === 's' || s.l === 'p') shield += groupCount[g] * (gn === s.n - 1 ? 0.85 : gn < s.n - 1 ? 1 : 0.35);
      else shield += groupCount[g];
    });
    return Math.max(z - shield, 0.7);
  });
}

function build(raw: RawElement, iso: RawIsotope[]): Element {
  const parsed = raw.subs.map(parseSub);
  const zeff = slater(raw.z, parsed);
  const coreZ = Object.keys(NOBLE).map(Number).filter((k) => k < raw.z).pop() ?? 0;
  const coreKeys = new Set(coreZ ? (RAW as RawElement[])[coreZ - 1].subs.map((s) => s.slice(0, 2)) : []);
  const subshells: Subshell[] = parsed.map((s, i) => {
    const l = L_OF[s.l];
    const nStar = N_STAR[s.n];
    return {
      key: `${s.n}${s.l}`, n: s.n, l: s.l, count: s.count, capacity: 2 * (2 * l + 1),
      core: coreKeys.has(`${s.n}${s.l}`), zeff: zeff[i],
      // <r> for a hydrogen-like orbital: (n^2 / Z) (3/2 - l(l+1)/(2 n^2)) a0, with Slater's n*.
      meanRadius: ((nStar * nStar) / zeff[i]) * (1.5 - (l * (l + 1)) / (2 * nStar * nStar)),
    };
  });
  const orbitals = subshells.reduce((a, s) => a + Math.min(s.count, s.capacity / 2), 0);
  const unpaired = subshells.reduce((a, s) => a + Math.min(s.count, s.capacity - s.count), 0);
  return {
    z: raw.z, symbol: raw.s, name: raw.n, weight: raw.w, period: raw.p, group: raw.g, block: raw.b, series: raw.ser,
    subshells, configuration: raw.subs.join(' '), core: coreZ ? NOBLE[coreZ] : null,
    shells: new Set(parsed.map((s) => s.n)).size, orbitals, unpaired, commonA: raw.A,
    vdw: raw.vdw, vdwEstimated: raw.vdwEst, covalent: raw.cov, density: raw.dens, melt: raw.mp, boil: raw.bp,
    electronegativity: raw.en, electronAffinity: raw.ea, ionisation: raw.ie, oxidation: raw.ox, cpk: raw.cpk,
    crust: raw.crust, sea: raw.sea, geochemical: raw.geo, discoveryYear: raw.year, discoverers: raw.who,
    discoveryPlace: raw.where, nameOrigin: raw.origin, description: raw.desc, uses: raw.uses, sources: raw.src,
    stableIsotopes: raw.stab,
    isotopes: iso.map(([a, mass, abundance, halfLife, spin, stable]) => ({ a, mass, abundance, halfLife, spin, stable })),
    nucleusRadius: 1.2 * Math.cbrt(raw.A),
  };
}

export const ELEMENTS: Element[] = (RAW as RawElement[]).map((r, i) => build(r, (RAW_ISO as RawIsotope[][])[i]));
export const MAX_Z = ELEMENTS.length;
export const elementAt = (z: number): Element => ELEMENTS[Math.min(MAX_Z, Math.max(1, z)) - 1];

/** Orbital family colours, one per block, the same on every atom. */
export const BLOCK_COLOUR: Record<Block, string> = { s: '#5f8ae0', p: '#2ea57a', d: '#c07f1e', f: '#a865d6' };
export const BLOCK_GLOW: Record<Block, [number, number, number]> = {
  s: [0.66, 0.78, 1.0], p: [0.4, 0.92, 0.66], d: [1.0, 0.7, 0.3], f: [0.82, 0.56, 1.0],
};
export const BLOCK_NAME: Record<Block, string> = { s: 's orbitals', p: 'p orbitals', d: 'd orbitals', f: 'f orbitals' };

/** Scale rings drawn round every atom: fixed sizes, shown when the atom reaches them. */
export const CLOUD_RINGS: { pm: number; style: 'solid' | 'dashed' }[] = [
  { pm: 150, style: 'solid' }, { pm: 200, style: 'dashed' }, { pm: 250, style: 'solid' }, { pm: 300, style: 'dashed' },
];

const SUP: Record<string, string> = { '0': '⁰', '1': '¹', '2': '²', '3': '³', '4': '⁴', '5': '⁵', '6': '⁶', '7': '⁷', '8': '⁸', '9': '⁹' };
export const sup = (n: number | string): string => String(n).replace(/\d/g, (d) => SUP[d]);

/** "[Xe] 4f¹⁴ 5d¹⁰ 6s¹" */
export function shortConfiguration(e: Element): string {
  const outer = e.subshells.filter((s) => !s.core).map((s) => s.key + sup(s.count)).join(' ');
  return e.core ? `[${e.core}] ${outer}` : outer;
}

/** A half-life in the handiest unit. `short` writes long spans as ky, My, Gy and Ty (thousand,
 *  million, billion and trillion years) where space is tight. */
export function formatHalfLife(s: number | null, short = false): string {
  if (s == null) return 'stable';
  const y = 3.156e7;
  const SHORT: Record<string, string> = { 'thousand y': 'ky', 'million y': 'My', 'billion y': 'Gy', 'trillion y': 'Ty' };
  const f = (v: number, u: string) => `${Number(v.toPrecision(3))} ${short ? SHORT[u] ?? u : u}`;
  if (s < 1e-15) return f(s * 1e18, 'as');
  if (s < 1e-12) return f(s * 1e15, 'fs');
  if (s < 1e-9) return f(s * 1e12, 'ps');
  if (s < 1e-6) return f(s * 1e9, 'ns');
  if (s < 1e-3) return f(s * 1e6, 'µs');
  if (s < 1) return f(s * 1e3, 'ms');
  if (s < 120) return f(s, 's');
  if (s < 7200) return f(s / 60, 'min');
  if (s < 172800) return f(s / 3600, 'h');
  if (s < y) return f(s / 86400, 'd');
  if (s < 1e3 * y) return f(s / y, 'y');
  if (s < 1e6 * y) return f(s / y / 1e3, 'thousand y');
  if (s < 1e9 * y) return f(s / y / 1e6, 'million y');
  if (s < 1e12 * y) return f(s / y / 1e9, 'billion y');
  return f(s / y / 1e12, 'trillion y');
}

/** The most abundant stable isotope, or the longest-lived one. */
export function keyIsotope(e: Element): Isotope | null {
  return e.isotopes.find((i) => i.a === e.commonA) ?? null;
}
